{
  "correction_rules": [
    "Adjust forecasts downward when model consistently overestimates prices in the early part of the 30-day horizon, especially after recent spikes.",
    "Apply a mild upward bias correction if sentiment remains neutral or slightly positive, as models tend to underreact to bullish sentiment.",
    "Reduce forecast volatility in the final 5–7 days of the 30-day horizon to avoid overshoots following sharp price increases.",
    "Incorporate mean reversion logic: if forecasted price deviates >1.5σ from recent 7-day average, revert toward that average with a smoothing factor.",
    "Avoid overreacting to short-term sentiment shifts — if sentiment is flat, do not amplify forecast swings beyond historical volatility bands."
  ]
}
